changeSet.sql:
ALTER TABLE "users" ADD COLUMN IF NOT EXISTS "agent" VARCHAR(256) DEFAULT NULL;
ALTER TABLE "users" ADD COLUMN IF NOT EXISTS "agent_company_name" VARCHAR(256) DEFAULT NULL;
ALTER TABLE "users" ADD COLUMN IF NOT EXISTS "agent_email_address" VARCHAR(256) DEFAULT NULL;
ALTER TABLE "users" ADD COLUMN IF NOT EXISTS "agent_phone_number" VARCHAR(256) DEFAULT NULL;
ALTER TABLE "users" ADD COLUMN IF NOT EXISTS "agent_phone_number_country_code" VARCHAR(10) DEFAULT NULL;
ALTER TABLE "users" ADD COLUMN IF NOT EXISTS "crc" BOOLEAN DEFAULT false;
ALTER TABLE "users" ADD COLUMN IF NOT EXISTS "crc_issuance_date" TIMESTAMP DEFAULT NULL;

COMMENT ON COLUMN "users"."agent" IS 'Indicates if a user is a public agent, private agent or he is not an agent.';
COMMENT ON COLUMN "users"."agent_company_name" IS 'The agent company name.';
COMMENT ON COLUMN "users"."agent_email_address" IS 'The agent email address.';
COMMENT ON COLUMN "users"."agent_phone_number" IS 'The agent phone number.';
COMMENT ON COLUMN "users"."agent_phone_number_country_code" IS 'The agent phone number country code.';
COMMENT ON COLUMN "users"."crc" IS 'Indicates if the user has provided a criminal record check.';
COMMENT ON COLUMN "users"."crc_issuance_date" IS 'The criminal record check issuance date.';

rollback.sql:
ALTER TABLE "users" DROP COLUMN IF EXISTS "agent";
ALTER TABLE "users" DROP COLUMN IF EXISTS "agent_company_name";
ALTER TABLE "users" DROP COLUMN IF EXISTS "agent_email_address";
ALTER TABLE "users" DROP COLUMN IF EXISTS "agent_phone_number";
ALTER TABLE "users" DROP COLUMN IF EXISTS "agent_phone_number_country_code";
ALTER TABLE "users" DROP COLUMN IF EXISTS "crc";
ALTER TABLE "users" DROP COLUMN IF EXISTS "crc_issuance_date";
